-- Resolve the actual product ID by stable slug; never assume identity value 1.
INSERT INTO public.product_variants (
    product_id, color_code, label, reference_variant_id,
    availability, stock_quantity, is_default, position
)
SELECT p.id, v.color_code, v.label, v.reference_variant_id,
       'available', NULL, v.is_default, v.position
FROM public.products AS p
CROSS JOIN (VALUES
    ('black', 'Black', '45871965307072'::TEXT, true, 0),
    ('silver', 'Silver', NULL::TEXT, false, 1)
) AS v(color_code, label, reference_variant_id, is_default, position)
WHERE p.slug = 'mw75-tumi'
ON CONFLICT (product_id, color_code) DO NOTHING;

-- Positions are zero-based, matching API schema; gallery labels use view 1..4.
-- Fallbacks normalize existing assets/ paths to /assets/ for the future API.
-- Gallery alt text follows script.js without assuming unseen photo details.
INSERT INTO public.product_images (variant_id, url, alt, fallback_url, position)
SELECT v.id, i.url, i.alt, i.fallback_url, i.position
FROM public.products AS p
JOIN public.product_variants AS v ON v.product_id = p.id
JOIN (VALUES
    ('black', 0, 'https://www.masterdynamic.com/cdn/shop/files/MW75B_TUMI_800x800_Hero.png?v=1769444695&width=800', 'Black MW75 TUMI wireless headphones, view 1', '/assets/mw75-black-fallback.svg'),
    ('black', 1, 'https://www.masterdynamic.com/cdn/shop/files/MW75B_TUMI_800x800_Front.png?v=1769444695&width=800', 'Black MW75 TUMI wireless headphones, view 2', '/assets/mw75-black-fallback.svg'),
    ('black', 2, 'https://www.masterdynamic.com/cdn/shop/files/MW75B_TUMI_800x800_Engraving.png?v=1769444695&width=800', 'Black MW75 TUMI wireless headphones, view 3', '/assets/mw75-black-fallback.svg'),
    ('black', 3, 'https://www.masterdynamic.com/cdn/shop/files/MW75B_TUMI_800x800_Straight_8b6fd9c0-e214-42cd-b617-eac997922263.png?v=1769444695&width=800', 'Black MW75 TUMI wireless headphones, view 4', '/assets/mw75-black-fallback.svg'),
    ('silver', 0, 'https://www.masterdynamic.com/cdn/shop/files/MW75S_TUMI_800x800_Hero.png?v=1769444695&width=800', 'Silver MW75 TUMI wireless headphones, view 1', '/assets/mw75-silver-fallback.svg'),
    ('silver', 1, 'https://www.masterdynamic.com/cdn/shop/files/MW75S_TUMI_800x800_Front.png?v=1769444695&width=800', 'Silver MW75 TUMI wireless headphones, view 2', '/assets/mw75-silver-fallback.svg'),
    ('silver', 2, 'https://www.masterdynamic.com/cdn/shop/files/MW75S_TUMI_800x800_Engraving.png?v=1769444695&width=800', 'Silver MW75 TUMI wireless headphones, view 3', '/assets/mw75-silver-fallback.svg'),
    ('silver', 3, 'https://www.masterdynamic.com/cdn/shop/files/MW75S_TUMI_800x800_Straight_f01c8c31-58db-4162-a823-25764eae06d7.png?v=1769444571&width=800', 'Silver MW75 TUMI wireless headphones, view 4', '/assets/mw75-silver-fallback.svg')
) AS i(color_code, position, url, alt, fallback_url) ON i.color_code = v.color_code
